import type { Fact } from '../lib/types';

/**
 * Curated, offline fact deck. Every fact carries a recall question so it can be
 * scheduled for spaced retrieval practice. In `opts` the FIRST option is always
 * the correct one — options are shuffled when shown.
 * `wiki` is the Wikipedia article used for "learn more" and for finding similar
 * live content.
 */
const f = (
  id: string, cat: string, tags: string, title: string, text: string,
  q: string, opts: [string, string, string, string], wiki: string,
): Fact => ({ id, cat, tags: tags.split(' '), title, text, quiz: { q, options: opts }, wiki });

